mkdir -p /tmp/sim && cat > /tmp/sim/s.py <<'E'
import sys
prog=[]
for l in open(sys.argv[1]):
    l=l.split(';')[0].strip()
    if l: prog.append(l.split())
R=dict(a=0,b=0,c=0,d=0)
def v(x): return R[x] if x in R else int(x)
pc=0;n=0;s=0
while 0<=pc<len(prog):
    i=prog[pc];op=i[0];n+=1;nxt=pc+1
    if op=='set':R[i[1]]=v(i[2])%65536
    elif op=='add':R[i[1]]=(R[i[1]]+v(i[2]))%65536
    elif op=='mul':R[i[1]]=(R[i[1]]*v(i[2]))%65536
    elif op=='mod':
        if v(i[2])>0:R[i[1]]%=v(i[2])
    elif op=='dec':R[i[1]]=max(0,R[i[1]]-1)
    elif op=='jnz':
        if v(i[1])!=0:nxt=pc+v(i[2])
    elif op=='skp':
        if v(i[1])<v(i[2]):nxt=pc+2
    elif op=='out':s+=v(i[1])
    pc=nxt
print(s,n)
E
cd /tmp/<path> && python3 -I /tmp/sim/s.py prog.pw9 | tee answer.txt
